		name = "狂狮",
		rare = 3,
		hero_desc = "塞赫麦特是科尔盖内部有名的“救火组长”，在骸震对策部身居要职的行动专员。\n虽然外表是一个性感的大姐姐，但却行为疯癫，神经大条，还拥有一通闲聊就把对方内心想法挖个底朝天的缜密心理侧写能力，让撒谎偷懒的同僚和心怀叵测的惯骗都避之不及。任何疑案重案交到她手上，都会被轻松解决。",
