	[1019] = {
		name = "疾风之枪",
		rare = 2,
		hero_desc = "深空之眼目前实际的管理者，是管理员培训时期的老师，也是后辈们最为仰慕的姐姐、前辈们最为信赖的帮手。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1019,
		weapon_name = "疾风之枪",
		race = 2,
		hero_dorm_skill = 1001,
		unlock_star = 200,
		role_type = 0,
		private = 0,
		impression = "不知不觉间，管理员已经成长为了第九部门的支柱。刚成为管理员的导师时，我就对管理员抱有很大期待，如今管理员能够成长到如此地步，实在超乎我的意料，作为指导者，没有比这更让人欣慰的事了。不论怎样强大的人都会有疲惫的时候，作为第九部门的管理员更是身兼重任。倘若需要寻求一个依靠的话，管理员大可以放心来找我，因为管理员一直是我重要的学生，也是我重要的人。",
		trial_stage = 4091019,
		weapon_desc = "能够支配空气流动的权钥，曾经在上古时代被古迪菲尔国当作祈求风调雨顺的仪器，在成为权钥后被隐科组改造成了休趁手的长枪外型。可以在战斗中降下「风神之柱」的神秘晶体，无法解析其内部成分，只在造成破坏的数分钟后就会随风飘散，有猜测是因异常的空气流动而从异空间来的金属体。",
