		impression = "观众经常说，能听见我歌声中的风和花香，其实那是我隔着舞台在展示我眼中的花海。当我脑海里一片漆黑的时候，我就无法站上舞台。\n这样的日子持续了很久，那段时间我脑海里只有聚光灯寂灭的黑暗，所以我很久没唱歌了。\n管理员……是可以让我重新产生画面的人。他的眼睛看向我，哪怕聚光灯没有亮起，我也能看见缤纷的色彩。\n所以我为他唱过歌，曾经唱过，以后也可以一直唱。\n……说的有点多了。提到歌声，提到……管理员，想说的话就不知不觉变多了。他就是一个这样让人期待的人。\n不用再多说，我相信我想表达的东西，他早就已经领悟到了。",
		trial_stage = 4091022,
		weapon_desc = "由枪械和杖组成的权钥，镶嵌的核心单元能够控制声波的振动，使其影响到范围内的其他物体或者生物，看上去就像是被声音「操控」一样。",
