	[1028] = {
		name = "轰雷",
		rare = 3,
		hero_desc = "深空之眼「雷小队」的队长，组织内最强的战斗力。在小队的各种行动中，即使岔子不断，最后也总能靠着她的实力强行完成。托尔极富正义感，但与狂野的战斗方式相对应的，处理事情也经常冲动。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1028,
		weapon_name = "妙尔尼尔",
		race = 4,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "要说的话……我觉得管理员有些太努力了。你想，管理员又要作为战场指挥官和我们一起上前线，还要处理那么多麻烦的工作，甚至还要对付弥弥尔那种性格别扭的臭猫，哇……光是想想就觉得累。从今往后，就由我来罩着管理员！虽然……可能没法帮管理员处理工作，但只要是外出作战，全部交给我就好了！看我把那些视骸通通揍飞！一只都别想碰着我们管理员！",
		trial_stage = 4091028,
		weapon_desc = "与托尔娇小的身形完全不匹的巨锤，后由隐科组进行了机械结构化改造。展开后能够形成雷电力场，释放雷霆击向敌人。内部搭载了和托尔战斗服上相同的高性能电磁模块，能够使托尔在力场中高速挥舞巨锤。",
