	[1039] = {
		name = "潮音",
		rare = 2,
		hero_desc = "深空之眼第九部的核心成员，比起正面和视骸作战，更擅长在队友身后用神力提供支援。\n性格温柔恬静，很擅长倾听他人的烦恼。",
		hide_info = 0,
		star_up_skill_template = 4,
		display_type = 0,
		id = 1039,
		weapon_name = "潮音",
		race = 1,
		hero_dorm_skill = 5001,
		unlock_star = 200,
		role_type = 0,
		private = 0,
		impression = "我与管理员结识得并不算晚，管理员一路上的成长，我都历历在目。明明才遭受了失去记忆这样的打击，却又能这么快地成长为第九部门当之无愧的核心成员，除了优秀和努力之外，我想，管理员一定还承受着旁人想象不到的压力吧。如果我能帮忙缓解更多的压力就好了……比如，充当管理员的心理咨询师之类的。其实，管理员常来我这里咨询，向我倾诉秘密，会这样做的管理员，必然是十分信任我。作为回报，我也会向管理员敞开心扉。希望有一天，我们之间能够不分彼此，心意相通……",
		trial_stage = 4091039,
		weapon_desc = "波塞冬的神力特性是少有的可以在战时修复修正者核心数据的类型，隐科组以传说中的三叉戟为原型对权钥进行了改造，帮助波塞冬更好控制这股能量。又因驱动神力时，这柄权钥会偶尔传出浪潮般的美妙声音，所以得名潮音。",
