	[1041] = {
		name = "铃兰之弦",
		rare = 3,
		hero_desc = "现任铃兰骑士团的团长，为人正直，秉承着正义、忠诚的骑士道，将守护欧莫菲斯的艺术秩序视为自己终生的使命。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1041,
		weapon_name = "鸣弦",
		race = 1,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "管理员是个很奇妙的人。许多人都说我平日里太严肃刻板难以接近，但管理员却不顾及这些，一直自然地与我相处，和管理员聊天，总会使我放松，也正是管理员开拓了我的视野，让我知道了许多以前不曾知晓的事物。我曾以为，想要守护秩序，守护「正义」，就必须踏上一条孤独而艰辛的道路，但事实却并非如此，只要有管理员在，我就绝不会孤单，因为管理员就是我最为重要的友人。",
		trial_stage = 4091041,
		weapon_desc = "由一把轻剑与一把重剑构成的组合式权钥，能够让使用者同时施展两种不同的战斗风格。剑身有着特殊的形体构造，据说两剑交错时能够演奏出悠扬的乐曲。",
		suffix = "雅典娜",
