	[1044] = {
		name = "不灭王权",
		rare = 3,
		hero_desc = "从拉的「生死」权能中孕育出的意识，继承原初权能以后具备了成为修正者的资格，后与奥西里斯分离，以「荷鲁斯」之名重新降临世间。虽然改变了身份，但她的性格并没有丝毫收敛，看起来仍然是暴躁又嘴硬的样子。",
		hide_info = 0,
		star_up_skill_template = 5,
		display_type = 0,
		id = 1044,
		weapon_name = "冥府灭却千城重碾",
		race = 2,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "他如果是修正者，我才懒得管……但毕竟是弱不禁风的人类，姑且保护一下好了。而且有时候也会说出一点中听的、有用的话，看在他把我带回来的份上，偶尔听一听就算给他面子了……",
		trial_stage = 4091044,
		weapon_desc = "冥王为击破阿波菲斯核心而构筑出的重型战刃。冥王获得荷鲁斯的身份后，这把武器被盖亚认证为其伴生权钥一同投放。荷鲁斯亲自为它命名。外型庞大但好在并不笨重，除了挥砍外似乎还有不少其他使用方式，偶尔能看到荷鲁斯抱着它琢磨灵光一现用出来却不知道该怎么用出第二次的招式。与生死权能相性极佳，可以借由该权钥令神力与权能互相增幅，发挥出更强大的力量。结合表面的纹饰来看，或许它并不完全来自冥王的想象，而可能与拉有关，但这已经不可考了。",
