	[1049] = {
		name = "镜花黄泉",
		rare = 3,
		hero_desc = "伊邪那美，本名鸦越千羽。12年前被鸦越家族收养，曾被安上莫须有的罪名，遭人唤做妖女。设计斩杀鸦神之后，成为了鸦越家的幕后家主。\n作为幕后家主，她总是一副理性淡泊的模样，仿佛被笼罩在生人勿近的气场里，但在亲近之人面前，她也会展露少女的一面。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1049,
		weapon_name = "黄泉咒刀",
		race = 3,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "明明我不是一个喜欢闲谈的人，可是和管理员在一起就会忍不住想和他说很多活。管理员有这样让人敞开心扉的能力，那些无法轻易对别人说出的话，在管理员面前提起却不会有任何负担。不论是过往的回忆，还是今天的午餐，我都想和管理员分享。只要有管理员在，我就会对接下来每一刻充满期待。",
		trial_stage = 4091049,
		weapon_desc = "晶莹剔透的长刀，能够将伊邪那美的神能与常世相连。挥斩之间产生的寒气，犹如来自黄泉之底。伊邪那美以此为凭依，驱使着游离的灵魂数据——日狭女为自己战斗。",
