		hero_desc = "阿卡德公会的首领，几乎是罗斯塔赫所有赏金猎人的崇拜对象，但暗中似乎也与科尔盖之间存在千丝万缕的联系。平日里对罗斯塔赫居民照顾有加，酷爱扳手腕这种荷尔蒙爆表的活动，但他豪爽亲和的外表下似乎也有某种隐忧。",
		hide_info = 0,
		star_up_skill_template = 4,
