	[1053] = {
		name = "怀阳",
		rare = 3,
		hero_desc = "羲和，除庚辰外虚恒最早觉醒的修正者。早期曾以道士身份混迹市井，目前长居若木宫镇压凶兽「混沌」。\n根据自身神能研究出了「天通术」，可以通过调整自身神能回路，实现改变体型和容貌的效果。虽然苏醒时年龄尚小，但因为不喜欢被当成孩子对待，羲和更习惯以成人样貌示人，平时说话也会显得「高深莫测」的样子，看起来像个隐士高人。",
		hide_info = 0,
		star_up_skill_template = 6,
		display_type = 0,
