		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "",
		trial_stage = 4091053,
		weapon_desc = "羲和的随身佩剑，鲜少有人知其来历。剑身锋芒内敛，剑柄镶嵌一枚光华流转的莹润玉石，执剑时颇有几分仙风道骨。\n早年曾陪羲和走南闯北，「路见不平，拔剑相助」是羲和的习惯。涤荡邪祟，事了拂衣去，羲和从不滞于名利。正如这柄剑名一般，遵从本心，自在归璞。",
