	[1054] = {
		name = "双司镇命",
		rare = 3,
		hero_desc = "无常，生于虚恒的双子修正者，姐姐名为无咎，妹妹名为必安。两人追随后土，常年驻守在囚云山上，看守着穷奇的地牢，同时也是冥途旅团的成员，合作承担着送葬人的职责。",
