		hero_desc = "四方院南交的代理人，医者出身，深知苍生疾苦。她在南交设立了医馆「赤炁堂」，并开设了许多分部，广传病征解法。\n陵光经常亲自坐镇医馆，为上门求医的患者救治，并倾听他们的生活琐碎。",
		hide_info = 0,
		star_up_skill_template = 3,
		display_type = 0,
		id = 1075,
		weapon_name = "五离",
		race = 9,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "对管理员的印象，那恐怕难以用简单的三两句话来概括。好像每一次接触，管理员都会让我见识到不同的模样。战场上的指挥若定，偶尔吃坏东西的冒冒失失，为友人解决烦心事时的细心温柔。不知不觉间，好像和管理员的距离就已经走到很近了，这大概也是管理员的天分吧。\n岁月悠长，世事繁杂，但每当与管理员相伴的时候，总让人心头稍霁。能够与管理员结识，是我之幸。",
		trial_stage = 4091075,
