	[1084] = {
		name = "朝约",
		rare = 1,
		hero_desc = "总是充满活力的新人小队成员，刚刚通过了考试加入深空之眼作战科。\n性格乐观开朗，似乎没有什么挫折可以打倒她。",
		hide_info = 0,
		star_up_skill_template = 1,
		display_type = 0,
		id = 1084,
		weapon_name = "卢恩之刃",
		race = 4,
		hero_dorm_skill = 1001,
		unlock_star = 100,
		role_type = 0,
		private = 0,
		impression = "管理员是个怎样的人……总觉得很难用一两句话就说清楚呢。比如说——他明明平时心思那么缜密，偶尔却会露出孩子气的一面，拉着我讨论最新一话的漫画剧情就能聊上半天；虽然平时总是油嘴滑舌，可一到了关键时刻，他却比任何人都要可靠。 还有最重要的一点……他明明只是普通的人类，却一直不遗余力地想要帮助身为修正者的我们。我有问过他哦，「为什么会来帮助第九部门的大家？」。结果他却说「帮助他人不需要什么特别的理由吧？」。实际上，我也正是这么想的。帮助他人本就不需要什么特别的理由。\n所以就像管理员每天都在为我们努力一样，我也会一直待在他身边，支持他、帮助他，去做到他想做的每件事。",
		trial_stage = 4091084,
		weapon_desc = "象征着既定与命运的长剑，曾是一柄举世闻名的圣剑，持有者皆是有过辉煌壮举的英雄，又或是被此剑选中的主人从一开始就被决定了成为英雄的宿命。剑脊刻着一行已经无法看清的卢恩古文，似乎是一首来自冰原地区的古诗谣。",
