	[1095] = {
		name = "苍鹭",
		rare = 3,
		hero_desc = "科尔盖重大犯罪对策部行动组长，拥有出色的情报获取能力。通过信息战避免与罪犯直接交火，将作战对平民造成的伤害降到最低。\n掌握着科尔盖情报部门的高级权限，似乎对所有人的秘密都了若指掌。一旦有人威胁到任务的进行，托特便会利用这些秘密，毫不留情地剔除这些阻碍，哪怕使用不光彩的手段。",
		hide_info = 0,
		star_up_skill_template = 1,
		display_type = 0,
		id = 1095,
		weapon_name = "囚笼圆舞",
