		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "管理员是无论什么时候都能破局的人。只要管理员出现，事情总会发生意想不到的转机。那些让人困顿其中的事，在管理员的陪伴下似乎都会变成沿途的插曲，囚笼一样沉闷的生活也能吹进自由的风。\n不论是从前还是现在，管理员都是我见过最有意思的人，让人好奇他最终会走到哪里。我会一直留在他的身边，直到见证每一场戏的结尾。",
