	[1099] = {
		name = "朔望",
		rare = 2,
		hero_desc = "对自我要求非常严格的修正者，雉小队的队长。\n虽然话语不多，但作战时的分析都简明扼要，是个能将任何任务放心托付的人。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1099,
		weapon_name = "朔望",
		race = 3,
		hero_dorm_skill = 4001,
		unlock_star = 200,
		role_type = 0,
		private = 0,
		impression = "说实话，当我第一次见到管理员时，我就能隐隐感觉到管理员的气场，温和却又带着与众不同的凌厉。作为人类，却站在对抗视骸的最前线；有勇气为同伴冒险，而不拘泥于完成任务……管理员的这些品质，无不令我敬佩。\n原本，我的生活只有剑术修行，但在管理员出现后，我才意识到，自己曾经忽视了周围许多有趣的事物。比起我身为剑士的才能和用处，管理员似乎更关注我内心的感受……唯有和管理员待在一起时，我才能感到片刻放松。",
		trial_stage = 4091099,
		weapon_desc = "一对久经淬炼的佩刀，曾经在无数艰险的任务中斩下目标首级。太刀「朔」以迅捷灵巧的作战风格为主，但「朔」的每一次挥刀都会为另一柄刀刃「望」积攒「暗面」。\n当「月之暗面」完全笼罩「望」时，对战斗过分的渴望就会在月读心中产生，此时她必须将这股力量通过另一种截然不同的战斗方式释放出来。",
		suffix = "月读",
