	[1111] = {
		name = "生魂",
		rare = 3,
		hero_desc = "与奥西里斯完全一样的相貌，但内在的主导人格是疯狂的「冥王」，拥有强大的力量，不屑于和其他修正者合作。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1111,
		weapon_name = "生魂",
		race = 2,
		hero_dorm_skill = 2104,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "一个弱小的人类，除了花言巧语以外就什么都不会，根本没有存在价值——我本来是这样想的。不过现在看来，我不得不收回这个评价了。他冒着被我烧掉脑子的风险也要进去救人，至少不是个只会耍嘴皮子的家伙。\n而且……管理员姑且还算得上有意思，再稍微陪这家伙多玩玩也没关系。至少，我不用担心这家伙会做出背叛我或者奥西里斯的事情，勉强就把管理员算作是同伴好了。",
		trial_stage = 4091111,
