		rare = 3,
		hero_desc = "每天都精神满满的利维坦，是个偶尔会犯迷糊的小可爱。\n虽然性格天真活泼，但意外的是个小醋坛子，请不要在她面前和维达尔表现得太过亲密。",
		hide_info = 0,
		star_up_skill_template = 4,
