	[1133] = {
		name = "天卫",
		rare = 3,
		hero_desc = "隐科组的主要负责人之一，开发了深空之眼中包括「弥弥尔系统」在内的大部分AI系统。以彻底消灭视骸为目标，凡事追求精准与高效。",
		hide_info = 0,
		star_up_skill_template = 4,
