		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "管理员加入综合科后，对隐科组的工作提供了许多支持。科研工作除了我们这些人的努力，还需要管理者有魄力给予充分的空间并做出远见性的决策，这两方面管理员都做得很好，我很钦佩。\n至于工作之外，我不是个擅长沟通的人，但管理员十分擅长察觉他人的内心并给予体贴的回应，好让对方产生愉悦的感受……诚恳地说，我十分期待和管理员沟通的时刻。",
		trial_stage = 4091133,
		weapon_desc = "海姆达尔研究空间构型理论后，为了将这项最新技术投入实战，将权钥残片进行改造强化后制成的装备组。她能够藉由这套装备组来将神力与空间技术融合，展开「彩虹桥」来实现空间转移，同时还能控制无人机提供战场援助能力。",
