		name = "追炎",
		rare = 1,
		hero_desc = "活泼好动、无忧无虑的前鬼坊是深空之眼里最大的麻烦精。她将过剩的精力全部用在了恶作剧上，并且自称有一个名叫「后鬼」的空气朋友，不过没人知道后鬼的存在真假。",
		hide_info = 0,
		star_up_skill_template = 2,
