	[1150] = {
		name = "绯染",
		rare = 3,
		hero_desc = "从小接受正统剑道训练的丰前坊，从剑道中学到的不仅仅是克敌的剑术，还有保护弱小、恪守礼节、尊师重道的剑道精神。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1150,
		weapon_name = "樱切",
		race = 3,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "管理员向来十分可靠，不论遇到怎样的突发情况，管理员都能做出最合理的判断，若不是管理员当时的下定的决心，我可能就选择放弃了也说不定，为了回应管理员对我的帮助，我也会全心全意的信任管理员。和管理员待在一起的时候，时间总是过得很快，我常常在想这是为什么……或许，是因为管理员的身侧总是有着让人安心的魔力吧。",
		trial_stage = 4091150,
		weapon_desc = "在丰前坊被收养前就陪伴在她身边的一把通体樱红的长刀，神力甚至溢出了刀锋化为流彩，人类都可以察觉到。\n这让丰前坊的养父误认为其是妖刀，因此将其封存多年，在丰前坊离家修炼时秘密交给月读。月读察觉到此刀的神力强大但是妖异，除非拥有强大的剑心，否则无法驾驭。",
