	[1170] = {
		name = "昭阳",
		rare = 3,
		hero_desc = "金乌，生于虚恒，自小随老师羲和在南交若木宫中修习天通术，因长居山中，颇有些不谙世事。但心思纯良正直，偶尔下山云游时，常模仿书中大侠行侠仗义，自称「逐日追云大侠」，不过时常因认知偏差闹出些乌龙。\n表面看起来大大咧咧行事跳脱，但淳善重诺，对于成为符合老师期望的弟子、成为保护世人的大侠怀着坚定不移的心志。随着修行日长，金乌也越来越多地开始思考自己的大侠之路究竟在何方，希望能早日接过老师的衣钵，成为独当一面的天通术传人。",
