	[1211] = {
		name = "魂羽",
		rare = 3,
		hero_desc = "与冥王分离的奥西里斯，在经历迷惘后，受到管理员的鼓励，向前踏出一步，迈向成为全新自我的道路。\n依旧和以前一样善良而温柔，但却比以前更加坚定勇敢，她决心成为更好的自己，用自己的方式帮上大家。",
