	[1248] = {
		name = "神威",
		rare = 3,
		hero_desc = "活泼好动、无忧无虑的前鬼坊是深空之眼里最大的麻烦精，不过近日来，她似乎变得成熟了不少，据本人所述，这是因为「英雄就要有英雄的做派」。",
		hide_info = 0,
		star_up_skill_template = 2,
		display_type = 0,
		id = 1248,
		weapon_name = "神威",
		race = 3,
		hero_dorm_skill = 0,
		unlock_star = 300,
		role_type = 0,
		private = 0,
		impression = "我为什么这么喜欢对管理员恶作剧？要说理由的话可太多了。管理员的反应很有趣，而且总是会原谅我，不过更重要的是，管理员总能知道我想要什么，无聊的时候会拉上我出去玩，沮丧的时候还会安慰我，和管理员在一起总是很开心！\n嗯哼~下次要怎么和管理员玩呢？光是对管理员恶作剧可不够……要不和管理员来一场恶作剧比赛吧~！我们互相恶作剧，看看谁才是真正的恶作剧大师，不过赢的肯定是我！",
		trial_stage = 4091248,
		weapon_desc = "隐科组为前鬼坊改装强化的便携式机甲操控中枢，平日里看起来像一只蓝白色的手环，一旦激活后就会为使用者召唤出具有飞行功能的战术装甲与威力强大的光束步枪。光束步枪具有变形功能，既可以通过喷射高浓度的神能粒子发动近身斩击，也可以将其高度压缩后发射附带大量电荷的强大炮击。",
