		impression = "管理员是个怎样的人……总觉得很难用一两句话就说清楚呢。比如说——他明明平时心思那么缜密，偶尔却会露出孩子气的一面，拉着我讨论最新一话的漫画剧情就能聊上半天；虽然平时总是油嘴滑舌，可一到了关键时刻，他却比任何人都要可靠。 还有最重要的一点……他明明只是普通的人类，却一直不遗余力地想要帮助身为修正者的我们。我有问过他哦，「为什么会来帮助第九部门的大家？」。结果他却说「帮助他人不需要什么特别的理由吧？」。实际上，我也正是这么想的。帮助他人本就不需要什么特别的理由。\n所以就像管理员每天都在为我们努力一样，我也会一直待在他身边，支持他、帮助他，去做到他想做的每件事。",
		trial_stage = 4091284,
		weapon_desc = "回应少女的意志而出现的长剑，剑身上回荡着过去与未来交刹时一闪而过的辉光。薇儿丹蒂能以意志驱动权钥，唤出由神能构成的持剑巨臂。不过这柄权钥的力量还并未被薇儿丹蒂完全掌握，依旧留有许多不为人知的谜团。",
		suffix = "薇儿丹蒂",
